const $=id=>document.getElementById(id);let serviceUrl='',serviceKey='',connected=false,file=null,result=null,busy=false,jobId=null,sequence=0;
const tabs=[...document.querySelectorAll('[data-tab]')];const allowed=new Set(['pdf','docx','pptx','html','png','jpg','jpeg']);
function feedback(message,type=''){const el=$('feedback');el.textContent=message;el.className='feedback '+type;el.hidden=!message}
function update(){ $('convertButton').disabled=!connected||!file||busy; $('fileInput').disabled=busy; $('sampleButton').disabled=busy; $('clearFile').disabled=busy; $('ocr').disabled=busy; $('connectionButton').disabled=busy; $('cancelButton').hidden=!busy;$('convertButton').firstChild.textContent=busy?'Converting… ':'Convert document '; }
function status(ok){connected=ok;$('connectionButton').classList.toggle('ready',ok);$('connectionLabel').textContent=ok?'Converter connected':'Connect converter';$('connectionNote').textContent=ok?'Ready. Documents are sent to the connected converter.':'Live uploads need a connected converter. You can explore the preconverted sample now.';$('connectionNote').classList.toggle('online',ok);update()}
async function request(path,options={}){const headers=new Headers(options.headers);if(serviceKey)headers.set('Authorization','Bearer '+serviceKey);const res=await fetch(serviceUrl+path,{...options,headers,signal:options.signal||AbortSignal.timeout(30000)});const content=res.headers.get('content-type')||'';if(!content.includes('application/json'))throw new Error('The converter is not available at this address.');const body=await res.json();if(!res.ok)throw new Error(typeof body.detail==='string'?body.detail:'The converter could not complete the request.');return body}
async function connect(url,key){const parsed=new URL(url||location.origin);const loopback=['127.0.0.1','localhost','[::1]'].includes(parsed.hostname);if(parsed.protocol!=='https:'&&!(loopback&&parsed.protocol==='http:'))throw new Error('Use an HTTPS service address, or localhost for a local demo.');if(parsed.username||parsed.password)throw new Error('Put the access key in its own field.');const next=parsed.origin+parsed.pathname.replace(/\/$/,'');const old={serviceUrl,serviceKey};serviceUrl=next;serviceKey=key;try{const health=await request('/api/health',{signal:AbortSignal.timeout(8000)});if(health.engine!=='Docling'||!health.ready)throw new Error('This address is not a ready Docling converter.');await request('/api/session',{signal:AbortSignal.timeout(8000)});status(true)}catch(error){serviceUrl=old.serviceUrl;serviceKey=old.serviceKey;throw error}}
function chooseFile(chosen){if(!chosen||busy)return;const ext=chosen.name.split('.').pop().toLowerCase();if(!allowed.has(ext)){feedback('Choose a PDF, DOCX, PPTX, HTML, PNG or JPEG file.','error');return}if(!chosen.size||chosen.size>10*1024*1024){feedback('Choose a nonempty document smaller than 10 MB.','error');return}file=chosen;$('fileName').textContent=file.name;$('fileSize').textContent=(file.size/1024).toFixed(1)+' KB';$('fileDetail').hidden=false;$('dropTitle').textContent='Document selected';$('dropSubtitle').textContent='Choose another file to replace it';feedback('');update()}
$('fileInput').addEventListener('change',e=>chooseFile(e.target.files[0]));const zone=$('dropZone');zone.tabIndex=0;zone.setAttribute('role','button');zone.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();if(!busy)$('fileInput').click()}});zone.addEventListener('dragover',e=>{e.preventDefault();if(!busy)zone.classList.add('dragover')});zone.addEventListener('dragleave',()=>zone.classList.remove('dragover'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('dragover');if(e.dataTransfer.files.length>1){feedback('Choose one document at a time.','error');return}chooseFile(e.dataTransfer.files[0])});$('clearFile').addEventListener('click',()=>{file=null;$('fileInput').value='';$('fileDetail').hidden=true;$('dropTitle').textContent='Drop a document here';$('dropSubtitle').textContent='or choose a file from your device';update()});
function addText(tag,text,parent=$('readable')){const element=document.createElement(tag);element.textContent=text;element.dir='auto';parent.append(element);return element}
function readable(markdown){const panel=$('readable');panel.replaceChildren();const lines=markdown.split('\n');let list=null;for(let i=0;i<lines.length;i++){const line=lines[i].trim();if(!line){list=null;continue}if(line.includes('|')&&i+1<lines.length&&/^\s*\|?\s*:?-{2,}/.test(lines[i+1])){const table=document.createElement('table');const cells=l=>l.replace(/^\|/,'').replace(/\|$/,'').split('|').map(c=>c.trim());const head=document.createElement('thead'),row=document.createElement('tr');cells(line).forEach(cell=>addText('th',cell,row));head.append(row);table.append(head);const body=document.createElement('tbody');i+=2;while(i<lines.length&&lines[i].includes('|')&&lines[i].trim()){const tr=document.createElement('tr');cells(lines[i].trim()).forEach(cell=>addText('td',cell,tr));body.append(tr);i++}i--;table.append(body);panel.append(table);list=null;continue}const heading=line.match(/^(#{1,6})\s+(.*)$/);if(heading){addText('h'+Math.min(heading[1].length,3),heading[2]);list=null;continue}const item=line.match(/^[-*+]\s+(.*)$/);if(item){if(!list){list=document.createElement('ul');panel.append(list)}addText('li',item[1],list);continue}list=null;addText('p',line).classList.add('markdown-line')}}
function showTab(name){tabs.forEach(tab=>{const active=tab.dataset.tab===name;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;$(tab.dataset.tab).hidden=!active})}tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>showTab(tab.dataset.tab));tab.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;else if(e.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')n=0;else if(e.key==='End')n=tabs.length-1;else return;e.preventDefault();showTab(tabs[n].dataset.tab);tabs[n].focus()})});
function showResult(data,sample=false){result=data;$('empty').hidden=true;$('result').hidden=false;$('downloads').hidden=false;$('resultName').textContent=data.filename;$('resultBadge').textContent=sample?'PRECONVERTED SAMPLE / DOCLING':'CONVERTED WITH DOCLING';$('stats').replaceChildren();[['Pages',data.stats.pages??'—'],['Sections',data.stats.sections],['Tables',data.stats.tables],['Words',data.stats.words]].forEach(([label,value])=>{const block=document.createElement('div');addText('b',String(value),block);addText('small',label,block);$('stats').append(block)});readable(data.markdown);$('markdown').textContent=data.markdown;$('json').textContent=JSON.stringify(data.document,null,2);showTab('readable');feedback(sample?'This sample was converted with Docling in advance. Connect a converter to process your own files.':data.partial?'Docling returned a partial result. Review the extracted content before using it.':'Conversion complete. Review the result before using it in learning materials.');if(innerWidth<680)$('result').scrollIntoView({behavior:'smooth',block:'start'})}
async function removeJob(){if(jobId){const id=jobId;jobId=null;try{await request('/api/jobs/'+encodeURIComponent(id),{method:'DELETE'})}catch{}}}
$('resetResult').addEventListener('click',async()=>{sequence++;result=null;await removeJob();$('result').hidden=true;$('downloads').hidden=true;$('empty').hidden=false;feedback('')});
$('sampleButton').addEventListener('click',async()=>{if(busy)return;try{const res=await fetch('./sample-result.json');if(!res.ok)throw new Error('The sample could not be loaded.');await removeJob();showResult(await res.json(),true)}catch(error){feedback(error.message,'error')}});
$('convertButton').addEventListener('click',async()=>{if(!file||!connected||busy)return;const run=++sequence;busy=true;update();await removeJob();feedback('Uploading document…','busy');const form=new FormData();form.append('file',file);form.append('ocr',String($('ocr').checked));let uploadedId=null;try{const job=await request('/api/jobs',{method:'POST',body:form});uploadedId=job.id;if(run!==sequence){await request('/api/jobs/'+encodeURIComponent(uploadedId),{method:'DELETE'});return}jobId=uploadedId;feedback('Docling is extracting the document. Scans and first-time model loading can take a few minutes.','busy');const deadline=Date.now()+10*60*1000;while(run===sequence){if(Date.now()>deadline)throw new Error('The conversion is taking longer than expected. Check the converter before trying again.');await new Promise(resolve=>setTimeout(resolve,1200));if(run!==sequence)return;const state=await request('/api/jobs/'+encodeURIComponent(jobId));if(run!==sequence)return;if(state.status==='complete'){showResult(state.result);break}if(state.status==='failed')throw new Error(state.error||'The document could not be converted.');if(state.status==='cancelled')throw new Error('The conversion was cancelled.')}}catch(error){if(run===sequence){feedback(error.message||'The converter could not be reached.','error');await removeJob()}}finally{if(run===sequence){busy=false;update()}}});
$('cancelButton').addEventListener('click',async()=>{sequence++;busy=false;update();feedback('Conversion cancelled. A running conversion may need to finish before the service accepts another file.');await removeJob()});
function download(text,extension,type){if(!result)return;const url=URL.createObjectURL(new Blob([text],{type}));const link=document.createElement('a');link.href=url;link.download=result.filename.replace(/\.[^.]+$/,'')+extension;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}$('downloadMd').addEventListener('click',()=>download(result.markdown,'.md','text/markdown;charset=utf-8'));$('downloadJson').addEventListener('click',()=>download(JSON.stringify(result.document,null,2),'.json','application/json;charset=utf-8'));
$('connectionButton').addEventListener('click',()=>{$('serviceUrl').value=serviceUrl||'';$('connectionError').hidden=true;$('connectionDialog').showModal()});$('closeDialog').addEventListener('click',()=>$('connectionDialog').close());$('connectionForm').addEventListener('submit',async e=>{e.preventDefault();$('connectSubmit').disabled=true;$('connectionError').hidden=true;try{await connect($('serviceUrl').value.trim(),$('serviceKey').value);$('serviceKey').value='';$('connectionDialog').close();feedback('Converter connected. You can now upload and convert a document.')}catch(error){$('connectionError').textContent=error.message==='Failed to fetch'?'Cannot reach this converter. Check its address, HTTPS connection and allowed origin settings.':error.message;$('connectionError').hidden=false}finally{$('connectSubmit').disabled=false}});
try{const config=await fetch('./config.json').then(r=>r.json());await connect(config.serviceUrl||location.origin,'')}catch{status(false)}
